"""Report actual A-D.2 coverage. Searches, accepted evidence and unresolved work
are separate quantities. Regression success does not mark final E/F as done.
"""
from __future__ import annotations
import collections
import csv
import hashlib
import json
import re
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
D=ROOT/'data/rs-estaduais';DOC=ROOT/'docs/rs-estaduais';A=DOC/'ad2';P=ROOT/'rs/deputados-estaduais'
def load(path,default=None):return json.loads(path.read_text(encoding='utf-8')) if path.exists() else default
def save(path,obj):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def csv_file(path,rows,fields):
    path.parent.mkdir(parents=True,exist_ok=True)
    with path.open('w',encoding='utf-8-sig',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=fields,delimiter=';',quoting=csv.QUOTE_ALL,extrasaction='ignore');writer.writeheader()
        for row in rows:
            safe={k:row.get(k,'') for k in fields}
            for k,value in safe.items():
                if isinstance(value,str) and value.startswith(('=','+','-','@','\t','\r')):safe[k]="'"+value
            writer.writerow(safe)
def run():
    records=load(D/'normalized.json')['candidates'];baseline=load(A/'baseline.json');applied=load(A/'applied.json')
    ledger=load(D/'ad2-research-ledger.json');by_id={r['candidate_id']:r for r in ledger}
    manifest=load(D/'manifest.json');history=[(c,h) for c in records for h in c['history'] if h['year']<2026]
    tests=(DOC/'unit-tests.txt').read_text(encoding='utf-8');match=re.search(r'Ran (\d+) tests?',tests)
    test_count=int(match[1]) if match else None;tests_ok=tests.rstrip().endswith('OK')
    browser=load(DOC/'browser-qa.json',{})
    after={'candidates':len(records),'policy_summaries':sum(bool(c['pautas']) for c in records),'policy_gaps':sum(not c['pautas'] for c in records),'current_offices':sum(bool(c['current_office']) for c in records),'with_activity':sum(bool(c['activities']) for c in records),'historical_vote_rows':sum(h.get('votes') is not None for _,h in history)}
    coverage=[]
    for c in records:
        review=by_id.get(c['id']);past=[h for h in c['history'] if h['year']<2026]
        evidence_pending=sum(h.get('votes') is None and not str(h.get('votes_status','')).startswith('not_applicable') for h in past)
        coverage.append({'candidate_id':c['id'],'name':c['name'],'party':c['party'],'number':c['number'],'policy_summary':bool(c['pautas']),'had_policy_summary_before':c['id'] in baseline['policy_summaries'],'searched_this_round':bool(review),'research_status':review['status'] if review else 'prior_summary_preserved','research_exhaustive':False,'query_count':len(review['searches']) if review else 0,'source_checks':len(review['source_checks']) if review else 0,'current_office_confirmed':bool(c['current_office']),'institutional_acts':len(c['activities']),'historical_votes_pending':evidence_pending,'next_action':'Aprofundar fontes individuais; a busca nominal não comprova ausência de propostas.' if not c['pautas'] else 'Revisão editorial final E ainda pendente.','tse_url':c['tse_url']})
    save(A/'candidate-coverage.json',coverage)
    csv_file(A/'candidate-coverage.csv',coverage,['candidate_id','name','party','number','policy_summary','had_policy_summary_before','searched_this_round','research_status','research_exhaustive','query_count','source_checks','current_office_confirmed','institutional_acts','historical_votes_pending','next_action','tse_url'])
    unresolved=[]
    for c,h in history:
        if h.get('votes') is not None:continue
        review=h.get('historical_registration_review',{})
        nonapp=str(h.get('votes_status','')).startswith('not_applicable')
        unresolved.append({'candidate_id':c['id'],'name':c['name'],'historical_id':h['candidate_id'],'year':h['year'],'office':h['office'],'round':h['round'],'electoral_unit':h.get('electoral_unit'),'vote_status':h.get('votes_status'),'requires_nominal_evidence':not nonapp,'historical_registration':review.get('registration_status'),'historical_totalization':review.get('totalization_status'),'historical_source':review.get('source_url'),'note':'Cargo de vice/suplência: não atribuir voto nominal próprio.' if nonapp else 'Total nominal não confirmado. Situação do cadastro histórico não é zero e não altera a candidatura de 2026.'})
    save(A/'historical-vote-pendencies.json',unresolved)
    csv_file(A/'historical-vote-pendencies.csv',unresolved,['candidate_id','name','historical_id','year','office','round','electoral_unit','vote_status','requires_nominal_evidence','historical_registration','historical_totalization','historical_source','note'])
    by_party={}
    for party in sorted({c['party'] for c in records}):
        group=[c for c in records if c['party']==party]
        by_party[party]={'candidates':len(group),'summaries':sum(bool(c['pautas']) for c in group),'remaining':sum(not c['pautas'] for c in group),'searched_ad2':sum(c['id'] in by_id for c in group)}
    report={'reported_at':datetime.now(timezone.utc).isoformat(),'cutoff':'2026-09-21','branch':'feat/rs-deputados-estaduais','issue':5,'pr':9,'baseline_commit':baseline['source_commit'],'before':baseline['counts'],'after':after,'delta':{k:after[k]-baseline['counts'][k] for k in after},'canonical_scope_correction_predates_this_round':True,'nominal_search_candidates':len(ledger),'nominal_search_queries':sum(len(r['searches']) for r in ledger),'individual_editorial_inputs':applied['editorial_evidence_candidates'],'new_summary_inputs':applied['new_summary_inputs'],'new_office_inputs':applied['new_office_inputs'],'historical_registrations_reviewed':applied['historical_statuses_reviewed'],'nominal_totals_added':applied['nominal_totals_added'],'historical_rows':len(history),'historical_rows_without_confirmed_total':sum(r['requires_nominal_evidence'] for r in unresolved),'historical_ticket_positions_without_own_nominal_vote':sum(not r['requires_nominal_evidence'] for r in unresolved),'candidates_with_past_votes':sum(any(h['year']<2026 and h.get('votes') is not None for h in c['history']) for c in records),'historical_vote_status':dict(collections.Counter(h.get('votes_status') for _,h in history)),'by_party':by_party,'unit_test_count':test_count,'unit_tests_passed':tests_ok,'browser_check_count':browser.get('check_count'),'browser_passed':browser.get('passed',False),'regression_gate':'passed' if tests_ok and browser.get('passed') else 'not_passed','research_exhaustive':False,'all_thematic_gaps_closed':after['policy_gaps']==0,'electoral_snapshot_refreshed':False,'electoral_snapshot_generated_at':manifest.get('snapshot_generated_at'),'merge_performed':False,'publication_performed':False,'E_final_editorial_review':'pending','F_fresh_electoral_snapshot_release_gate':'pending','html_sha256':hashlib.sha256((P/'index.html').read_bytes()).hexdigest(),'limitations':['Uma busca nominal foi registrada para cada uma das 99 lacunas da base corrigida; isso não é pesquisa exaustiva.','As sínteses incluem posições atuais e declarações ou atos históricos explicitamente datados; não equivalem a programas completos de 2026.','Diretórios municipais e estaduais inacessíveis não foram usados para confirmar mandatos.','A referência nacional de 2014 usa membro BR próprio; os demais totais não foram convertidos em nacionais.','Os 11 totais ainda pendentes não viraram zero após a leitura da situação histórica.','Testes de regressão não substituem E/F nem autorizam merge.']}
    save(A/'report.json',report)
    # Current delivery metadata is cumulative, while older phase reports remain distinguishable.
    current=load(DOC/'delivery-report.json',{})
    current.update({'current_phase':'A-D.2','scope_census':after['candidates'],'policy_summaries':after['policy_summaries'],'policy_gaps':after['policy_gaps'],'documented_acts_candidates':after['with_activity'],'current_offices_confirmed':after['current_offices'],'past_vote_rows':after['historical_vote_rows'],'past_vote_candidates':report['candidates_with_past_votes'],'past_history_rows':len(history),'unit_tests_passed':tests_ok,'unit_test_count':test_count,'browser_checks':browser.get('check_count'),'technical_gate':report['regression_gate'],'editorial_gate':'partial_with_explicit_gaps','ad2_report':'ad2/report.json','html_sha256':report['html_sha256']})
    save(DOC/'delivery-report.json',current)
    lines=['# RS / Deputados estaduais 2026 — A–D.2','', '**Pesquisa incremental executada; fechamento editorial integral ainda pendente.**','', '## Base e recorte','', 'A correção canônica anterior a esta execução acrescentou duas candidaturas da REDE e duas do PSTU: a base recebida tinha 149 candidaturas, 50 sínteses e 99 lacunas. A–D.2 preserva essa correção; não atribui os quatro novos registros a esta pesquisa nem remove siglas do recorte.', '', '## Resultado comparado','', '| Cobertura documental | Antes de A–D.2 | Depois |','|---|---:|---:|']
    labels={'candidates':'Candidaturas','policy_summaries':'Sínteses individuais de temas','policy_gaps':'Fichas sem síntese temática','current_offices':'Mandatos atuais confirmados','with_activity':'Fichas com atos institucionais','historical_vote_rows':'Linhas históricas com votos conferidos'}
    for key,label in labels.items():lines.append(f'| {label} | {baseline["counts"][key]} | {after[key]} |')
    lines+=['', 'A tabela mede cobertura documental, não qualidade ou preferência política. Os grupos se sobrepõem.', '', '## A — pesquisa individual','',f'Foi registrada busca nominal para as {len(ledger)} lacunas iniciais, com {report["nominal_search_queries"]} consultas preservadas. {applied["new_summary_inputs"]} novas sínteses foram apoiadas por fontes individuais. As demais {after["policy_gaps"]} lacunas exigem aprofundamento; uma busca ou um link indisponível não demonstram ausência de propostas.', '', 'O registro distingue apresentações individuais, entrevistas, opiniões assinadas, atos municipais e declarações históricas. Textos de 2025 ou anteriores são identificados como históricos, não como programa completo de 2026. A entrevista de setembro de Cleonice Back complementa a insuficiência antes registrada no site de campanha.', '', '## B e C — mandatos e atos','', 'Foi acrescentada a confirmação de Bruno Berté como vereador de Carazinho na relação institucional Atual Legislatura. A presidência mencionada em entrevista de 2025 não foi transferida para o presente. As doze chamadas aos sistemas municipais de São Jerônimo, Esteio e Jaguari retornaram timeout; nenhuma confirmação foi fabricada.', '', 'Foram acrescentados registros de proposta, aprovação legislativa, autoria de documento de comissão, reunião e posses históricas. A autoria de certidão não vira voto individual; anúncio de recurso não vira entrega; a aprovação legislativa não é descrita como implantação; a posse de suplente no passado não prova exercício atual.', '', '## D — totais e registros antigos','',f'Foram incorporados {applied["nominal_totals_added"]} totais: duas disputas anteriores de Rogério Chimanski e a disputa presidencial de Luciana Genro em 2014, esta em fonte nacional BR. Agora há {after["historical_vote_rows"]} totais conferidos em {len(history)} linhas históricas. Restam {report["historical_rows_without_confirmed_total"]} totais sem confirmação e {report["historical_ticket_positions_without_own_nominal_vote"]} posições de vice/suplência sem voto nominal próprio.', '', 'As 14 fichas históricas do DivulgaCand foram relidas com ID, ano, cargo e nome conciliados. Sua situação foi anotada exclusivamente no histórico; não substitui a situação de 2026. Renúncia ou indeferimento histórico não foi usado para inventar um zero nominal. Os arquivos por município/zona têm CRC e SHA-256 de seus membros; não se declara hash integral de arquivo nacional acessado por intervalos.', '', '## Regressão e isolamento','',f'Resultado: {report["regression_gate"]}. Testes unitários: {test_count}; verificações Chromium: {browser.get("check_count")}. A verificação cobre dados, preservação de fontes, contexto eleitoral, repetição das etapas, controles de histórico e responsividade. E/F seguem pendentes.', '', 'Mudanças restritas à edição RS/estaduais, testes, documentação e workflows próprios. Não foram feitos merge, publicação, nova coleta eleitoral completa ou alterações às outras frentes. A configuração canônica compartilhada foi apenas lida.', '', '## Arquivos','', '- `candidate-coverage.csv` e `.json`: as 149 candidaturas e o estado efetivo da pesquisa.','- `historical-vote-pendencies.csv` e `.json`: cada nulo com contexto e distinção entre pendência e cargo sem voto nominal próprio.','- `report.json`: métricas desta execução e limitações.','- `data/rs-estaduais/ad2-*.json`: consultas, fontes aceitas, fontes insuficientes e evidências eleitorais.','- `rs/deputados-estaduais/pesquisa.json`: consulta pública ao registro de pesquisa.','', '## Próximo requisito de fechamento','', 'Aprofundar as fontes das fichas ainda sem síntese, ampliar confirmações institucionais e concluir E/F sobre a versão consolidada. Não é necessário inventar um programa para cada pessoa; é necessário documentar pesquisa suficiente e distinguir com clareza o que foi verificado do que permanece desconhecido.','']
    (A/'ENTREGA-A-D.2.md').write_text('\n'.join(lines),encoding='utf-8')
    print(json.dumps({k:v for k,v in report.items() if k not in ('by_party','limitations')},ensure_ascii=False,indent=2))
if __name__=='__main__':run()
